CREATE TABLE support_feedback (id CHAR(36) NOT NULL PRIMARY KEY,legacy_id BIGINT NOT NULL,username VARCHAR(50) NOT NULL,email VARCHAR(100) NOT NULL,phone VARCHAR(20),category VARCHAR(50) NOT NULL,title VARCHAR(200) NOT NULL,content TEXT NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_support_feedback_legacy UNIQUE(legacy_id));
CREATE TABLE support_feedback_migration (legacy_id BIGINT NOT NULL PRIMARY KEY,migration_key VARCHAR(128) NOT NULL,payload_sha256 CHAR(64) NOT NULL,feedback_id CHAR(36) NOT NULL,imported_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_support_feedback_migration FOREIGN KEY(feedback_id) REFERENCES support_feedback(id));
